export type FishSpec = {
  id: string; name: string; sci: string; zone: ZoneId; d: [number, number]; size: number; r?: 1 | 2 | 3 | 4;
  body: Sh; look: Look; hab: Habitat; n: number; g?: number; desc: string;
  region?: Region; speed?: number; flee?: number; spread?: number; swim?: [number, number, number]; metal?: number; photoRange?: number; glow?: number; behavior?: SpeciesDef['behavior']; pitch?: number;
  aggro?: SpeciesDef['aggro'];
};

export function F(s: FishSpec): SpeciesDef {
  const h = HAB[s.hab];
  const sz = s.size;
  return {
    id: s.id, name: s.name, sci: s.sci, zone: s.zone, depth: s.d, size: sz, rarity: s.r ?? 1,
    desc: s.desc, hint: `${zoneLabel[s.zone]}。${h.label}。`,
    kind: 'fish', fish: s.body,
    paint: (p: Paint) => paintLook(p, s.look),
    count: s.n, groups: s.g ?? (['perch', 'burrow', 'under', 'coralPick', 'cleaner'].includes(s.hab) ? s.n : Math.max(1, Math.round(s.n / 6))),
    behavior: s.behavior ?? h.behavior, region: s.region ?? h.region,
    speed: s.speed ?? h.speed * Math.min(2.5, 0.6 + sz * 2), flee: s.flee ?? h.flee, spread: s.spread ?? h.spread,
    swim: s.swim ?? [Math.max(0.8, 5.5 - sz * 4), sz < 0.4 ? 0.05 : 0.04, 4],
    mat: { metal: s.metal ?? 0.08, rough: (s.metal ?? 0) > 0.3 ? 0.3 : 0.5, glow: s.glow },
    photoRange: s.photoRange ?? Math.max(3.5, Math.min(30, sz * 14 + 3)),
    hab: s.hab, habLabel: h.label, pitch: s.pitch, aggro: s.aggro,
  };
}
